"""Dataset helpers."""

from __future__ import annotations

from typing import Any, Iterable, Mapping

from datasets import Dataset


def to_dataset(data: Dataset | list[Mapping[str, Any]] | dict[str, list[Any]] | None) -> Dataset | None:
    """Convert common dataset inputs to a HuggingFace Dataset."""

    if data is None:
        return None
    if isinstance(data, Dataset):
        return data
    if isinstance(data, dict):
        return Dataset.from_dict(data)
    return Dataset.from_list(list(data))


def slice_dataset(dataset: Dataset, num_examples: int | None = None) -> Dataset:
    """Limit dataset size when requested."""

    if num_examples is None or num_examples < 0:
        return dataset
    if num_examples >= len(dataset):
        return dataset
    return dataset.select(range(num_examples))

