"""Helpers for converting between string and chat-style message formats."""

from __future__ import annotations

import json
from copy import deepcopy
from typing import Any, Iterable

from verifiers.types import ChatMessage, Messages


def clone_messages(messages: list[ChatMessage]) -> list[ChatMessage]:
    """Return a deep copy of message data."""

    return deepcopy(messages)


def is_chat_messages(value: Messages | Any) -> bool:
    """Return True when the input looks like a list of chat messages."""

    return isinstance(value, list)


def message_content_to_text(content: Any) -> str:
    """Normalize message content into a readable string."""

    if content is None:
        return ""
    if isinstance(content, str):
        return content
    if isinstance(content, list):
        parts: list[str] = []
        for item in content:
            if isinstance(item, dict):
                if "text" in item:
                    parts.append(str(item["text"]))
                else:
                    parts.append(json.dumps(item, sort_keys=True))
            else:
                parts.append(str(item))
        return "".join(parts)
    if isinstance(content, dict):
        return json.dumps(content, sort_keys=True)
    return str(content)


def ensure_messages(prompt: Messages, role: str = "user") -> list[ChatMessage]:
    """Convert a prompt to chat messages when needed."""

    if isinstance(prompt, list):
        return clone_messages(prompt)
    return [{"role": role, "content": str(prompt)}]


def messages_to_text(messages: Messages) -> str:
    """Flatten a message list into a readable transcript."""

    if isinstance(messages, str):
        return messages
    lines: list[str] = []
    for message in messages:
        role = message.get("role", "unknown")
        content = message_content_to_text(message.get("content"))
        lines.append(f"{role}: {content}")
    return "\n".join(lines)


def append_messages(base: list[ChatMessage], extra: Iterable[ChatMessage]) -> list[ChatMessage]:
    """Append messages into a chat transcript."""

    base.extend(clone_messages(list(extra)))
    return base

