"""Regex-based XML field extraction for structured model outputs."""

from __future__ import annotations

import re
from collections.abc import Callable
from types import SimpleNamespace
from typing import Any

from verifiers.parsers.parser import Parser
from verifiers.types import Messages


class XMLParser(Parser):
    """Extract XML fields into a structured namespace."""

    def __init__(
        self,
        fields: list[str | tuple[str, ...]],
        answer_field: str = "answer",
        extract_fn: Callable[[str], str] | None = None,
    ):
        super().__init__(extract_fn=extract_fn)
        self.fields = fields
        self.answer_field = answer_field

    def _resolve_field_specs(self) -> list[tuple[str, tuple[str, ...]]]:
        specs: list[tuple[str, tuple[str, ...]]] = []
        for field in self.fields:
            if isinstance(field, tuple):
                specs.append((field[0], tuple(field)))
            else:
                specs.append((field, (field,)))
        return specs

    def _extract_tag(self, text: str, tag: str) -> str | None:
        pattern = re.compile(
            rf"<{re.escape(tag)}\b[^>]*>(.*?)</{re.escape(tag)}>",
            flags=re.IGNORECASE | re.DOTALL,
        )
        match = pattern.search(text)
        return match.group(1).strip() if match else None

    def parse(self, text: str) -> SimpleNamespace:
        """Parse XML-like text into a namespace with requested fields."""

        data: dict[str, Any] = {}
        for canonical, aliases in self._resolve_field_specs():
            value: str | None = None
            for alias in aliases:
                value = self._extract_tag(text, alias)
                if value is not None:
                    break
            data[canonical] = self.extract_fn(value) if value is not None else None
        return SimpleNamespace(**data)

    def parse_answer(self, completion: Messages) -> str | None:
        """Extract the configured answer field from text or chat messages."""

        if completion is None:
            return None
        if isinstance(completion, list):
            base = super().parse_answer(completion)
        else:
            base = str(completion)
        if base is None:
            return None
        parsed = self.parse(base)
        for canonical, aliases in self._resolve_field_specs():
            if canonical == self.answer_field or self.answer_field in aliases:
                value = getattr(parsed, canonical, None)
                return str(value) if value is not None else None
        value = getattr(parsed, self.answer_field, None)
        return str(value) if value is not None else None

