"""Shared types and result containers used across the verifiers package."""

from __future__ import annotations

from dataclasses import dataclass, field
from typing import Any, Awaitable, Callable, Iterable, Iterator, Literal, Mapping, MutableMapping, TypedDict


class ChatMessage(TypedDict, total=False):
    """A chat message compatible with OpenAI-style APIs."""

    role: str
    content: Any
    name: str
    tool_calls: list[dict[str, Any]]
    tool_call_id: str


Messages = str | list[ChatMessage]
State = dict[str, Any]
Info = dict[str, Any]
MessageType = Literal["chat", "completion"]
SamplingArgs = dict[str, Any]
RewardFunc = Callable[..., float | Awaitable[float]]


@dataclass(slots=True)
class RolloutScore:
    """Scores for a single rollout."""

    metrics: dict[str, float] = field(default_factory=dict)
    reward: float = 0.0

    def __getitem__(self, key: str) -> float | dict[str, float]:
        if key == "metrics":
            return self.metrics
        if key == "reward":
            return self.reward
        return self.metrics[key]

    def keys(self) -> list[str]:
        return [*self.metrics.keys(), "reward"]

    def to_dict(self) -> dict[str, Any]:
        return {**self.metrics, "reward": self.reward}


@dataclass(slots=True)
class RolloutScores:
    """Scores for multiple rollouts."""

    metrics: dict[str, list[float]] = field(default_factory=dict)
    reward: list[float] = field(default_factory=list)

    @classmethod
    def from_scores(cls, scores: Iterable[RolloutScore]) -> "RolloutScores":
        materialized = list(scores)
        metric_names: set[str] = set()
        for score in materialized:
            metric_names.update(score.metrics)
        metrics = {name: [] for name in sorted(metric_names)}
        rewards: list[float] = []
        for score in materialized:
            for name in metrics:
                metrics[name].append(float(score.metrics.get(name, 0.0)))
            rewards.append(float(score.reward))
        return cls(metrics=metrics, reward=rewards)

    def __getitem__(self, key: str) -> list[float] | dict[str, list[float]]:
        if key == "metrics":
            return self.metrics
        if key == "reward":
            return self.reward
        return self.metrics[key]

    def keys(self) -> list[str]:
        return [*self.metrics.keys(), "reward"]

    def to_dict(self) -> dict[str, Any]:
        return {**self.metrics, "reward": self.reward}


@dataclass(slots=True)
class GenerateOutputs:
    """Collected outputs from environment generation or evaluation."""

    prompt: list[Messages] = field(default_factory=list)
    completion: list[Messages] = field(default_factory=list)
    answer: list[str] = field(default_factory=list)
    state: list[State] = field(default_factory=list)
    task: list[str] = field(default_factory=list)
    info: list[Info] = field(default_factory=list)
    metrics: dict[str, list[float]] = field(default_factory=dict)
    reward: list[float] = field(default_factory=list)
    example_id: list[int | None] = field(default_factory=list)

    def __len__(self) -> int:
        return len(self.prompt)

    def to_dict(self) -> dict[str, Any]:
        return {
            "prompt": self.prompt,
            "completion": self.completion,
            "answer": self.answer,
            "state": self.state,
            "task": self.task,
            "info": self.info,
            "metrics": self.metrics,
            "reward": self.reward,
            "example_id": self.example_id,
        }


@dataclass(slots=True)
class ProcessedOutputs:
    """Tokenized environment results ready for model training."""

    prompt_ids: list[list[int]]
    prompt_mask: list[list[int]]
    completion_ids: list[list[int]]
    completion_mask: list[list[int]]
    rewards: list[float]
    states: list[State]

    def to_dict(self) -> dict[str, Any]:
        return {
            "prompt_ids": self.prompt_ids,
            "prompt_mask": self.prompt_mask,
            "completion_ids": self.completion_ids,
            "completion_mask": self.completion_mask,
            "rewards": self.rewards,
            "states": self.states,
        }


def merge_metrics(existing: MutableMapping[str, list[float]], incoming: Mapping[str, list[float]]) -> None:
    """Append incoming metric lists into an existing metric mapping."""

    for name, values in incoming.items():
        existing.setdefault(name, [])
        existing[name].extend(values)

