"""Base parser for extracting answers from text or chat messages."""

from __future__ import annotations

from collections.abc import Callable
from typing import Any

from verifiers.types import ChatMessage, Messages
from verifiers.utils.message_utils import message_content_to_text


class Parser:
    """Basic text parser with helpers for chat-style message lists."""

    def __init__(self, extract_fn: Callable[[str], Any] | None = None):
        self.extract_fn = extract_fn or (lambda x: x)

    def parse(self, text: str) -> Any:
        """Parse raw text into a structured answer."""

        return self.extract_fn(text)

    def parse_answer(self, completion: Messages) -> str | None:
        """Extract the final assistant answer from text or messages."""

        if completion is None:
            return None
        if isinstance(completion, str):
            parsed = self.parse(completion)
            return str(parsed) if parsed is not None else None
        assistants = self.get_assistant_messages(completion)
        if not assistants:
            return None
        content = message_content_to_text(assistants[-1].get("content"))
        parsed = self.parse(content)
        return str(parsed) if parsed is not None else None

    def get_format_reward_func(self) -> Callable[..., float]:
        """Return a reward function that checks whether parsing succeeds."""

        def reward_func(completion: Messages, **_: Any) -> float:
            answer = self.parse_answer(completion)
            return float(answer is not None and str(answer).strip() != "")

        reward_func.__name__ = "format_reward"
        return reward_func

    def _filter_messages(self, completion: list[ChatMessage], role: str) -> list[ChatMessage]:
        return [message for message in completion if message.get("role") == role]

    def get_assistant_messages(self, completion: list[ChatMessage]) -> list[ChatMessage]:
        """Return assistant messages from a conversation."""

        return self._filter_messages(completion, "assistant")

    def get_system_messages(self, completion: list[ChatMessage]) -> list[ChatMessage]:
        """Return system messages from a conversation."""

        return self._filter_messages(completion, "system")

    def get_user_messages(self, completion: list[ChatMessage]) -> list[ChatMessage]:
        """Return user messages from a conversation."""

        return self._filter_messages(completion, "user")

    def get_tool_messages(self, completion: list[ChatMessage]) -> list[ChatMessage]:
        """Return tool messages from a conversation."""

        return self._filter_messages(completion, "tool")

