"""Mock OpenAI-compatible async client used by the test suite."""

from __future__ import annotations

import json
from dataclasses import dataclass
from typing import Any


@dataclass(slots=True)
class _MockChatMessage:
    role: str = "assistant"
    content: str | None = None
    tool_calls: list[dict[str, Any]] | None = None


@dataclass(slots=True)
class _MockChatChoice:
    message: _MockChatMessage
    finish_reason: str = "stop"


@dataclass(slots=True)
class _MockTextChoice:
    text: str
    finish_reason: str = "stop"


@dataclass(slots=True)
class _MockResponse:
    choices: list[Any]


class _MockChatCompletions:
    def __init__(self, parent: "MockAsyncOpenAI"):
        self.parent = parent

    async def create(self, model: str, messages: list[dict[str, Any]], **kwargs: Any) -> _MockResponse:
        del model, kwargs
        return self.parent._chat_response(messages)


class _MockTextCompletions:
    def __init__(self, parent: "MockAsyncOpenAI"):
        self.parent = parent

    async def create(self, model: str, prompt: str, **kwargs: Any) -> _MockResponse:
        del model, kwargs
        return self.parent._text_response(prompt)


class _MockChatNamespace:
    def __init__(self, parent: "MockAsyncOpenAI"):
        self.completions = _MockChatCompletions(parent)


class MockAsyncOpenAI:
    """A deterministic async client with OpenAI-like chat and completion APIs."""

    def __init__(self):
        self.chat_completions: dict[str, dict[str, Any]] = {}
        self.text_completions: dict[str, dict[str, Any]] = {}
        self.default_chat_response = "This is a test response"
        self.default_text_response = "This is a test response"
        self.default_chat_tool_calls: list[dict[str, Any]] | None = None
        self.default_chat_finish_reason = "stop"
        self.default_text_finish_reason = "stop"
        self.base_url = "http://localhost/v1/"
        self.chat = _MockChatNamespace(self)
        self.completions = _MockTextCompletions(self)
        self.request_log: list[dict[str, Any]] = []

    def _messages_to_key(self, messages: list[dict[str, Any]]) -> str:
        return json.dumps(messages, sort_keys=True, default=str)

    def add_chat_response(
        self,
        messages: list[dict[str, Any]],
        response: str,
        finish_reason: str = "stop",
        tool_calls: list[dict[str, Any]] | None = None,
    ) -> None:
        """Register a chat response for a specific message list."""

        self.chat_completions[self._messages_to_key(messages)] = {
            "content": response,
            "finish_reason": finish_reason,
            "tool_calls": tool_calls,
        }

    def add_text_response(self, prompt: str, response: str, finish_reason: str = "stop") -> None:
        """Register a text completion response for a specific prompt."""

        self.text_completions[str(prompt)] = {
            "text": response,
            "finish_reason": finish_reason,
        }

    def set_default_responses(
        self,
        chat: str | None = None,
        text: str | None = None,
        chat_tool_calls: list[dict[str, Any]] | None = None,
    ) -> None:
        """Update fallback responses used when no exact mapping exists."""

        if chat is not None:
            self.default_chat_response = chat
        if text is not None:
            self.default_text_response = text
        if chat_tool_calls is not None:
            self.default_chat_tool_calls = chat_tool_calls

    def reset(self) -> None:
        """Clear registered responses and request history."""

        self.chat_completions.clear()
        self.text_completions.clear()
        self.request_log.clear()

    def _chat_response(self, messages: list[dict[str, Any]]) -> _MockResponse:
        key = self._messages_to_key(messages)
        payload = self.chat_completions.get(
            key,
            {
                "content": self.default_chat_response,
                "finish_reason": self.default_chat_finish_reason,
                "tool_calls": self.default_chat_tool_calls,
            },
        )
        self.request_log.append({"type": "chat", "messages": messages})
        message = _MockChatMessage(
            content=payload["content"],
            tool_calls=payload.get("tool_calls"),
        )
        return _MockResponse(choices=[_MockChatChoice(message=message, finish_reason=payload["finish_reason"])])

    def _text_response(self, prompt: str) -> _MockResponse:
        payload = self.text_completions.get(
            str(prompt),
            {
                "text": self.default_text_response,
                "finish_reason": self.default_text_finish_reason,
            },
        )
        self.request_log.append({"type": "completion", "prompt": prompt})
        return _MockResponse(choices=[_MockTextChoice(text=payload["text"], finish_reason=payload["finish_reason"])])

