from __future__ import annotations

import re

from verifiers import ThinkParser


def test_think_parser_strips_think_blocks() -> None:
    parser = ThinkParser()
    assert parser.parse("<think>Let me think...</think>The answer is 42.") == "The answer is 42."


def test_think_parser_supports_custom_extract_fn() -> None:
    parser = ThinkParser(
        extract_fn=lambda text: (
            match.group(1) if (match := re.search(r"\\boxed\{([^}]+)\}", text)) else text
        )
    )
    assert parser.parse("<think>Reasoning</think>The answer is \\boxed{42}.") == "42"


def test_think_parser_extracts_reasoning_blocks() -> None:
    parser = ThinkParser()
    assert parser.extract_reasoning("<think>first</think><think>second</think>") == ["first", "second"]

